// Read-only pages derive from confirmed records and existing explicit dialogue receipts.
var notebookPage=0,notebookTab='pending',notebookReturn=null,notebookRows=null,notebookSeriesRows=null,notebookGeneration=0;
const notebookDialog=document.createElement('dialog');notebookDialog.id='manager-notebook';notebookDialog.setAttribute('aria-labelledby','notebook-title');document.body.append(notebookDialog);
function notebookScenes(){if(typeof ClubStory.scenes==='function')return ClubStory.scenes(season).sort((a,b)=>b.year-a.year||b.round-a.round||a.id.localeCompare(b.id));const seen=new Set(),out=[];for(let year=1;year<=season.year;year++){for(const e of ClubStory.events(season,year)){const d=ClubStory.scene(season,e.id);if(!d||seen.has(d.id))continue;seen.add(d.id);out.push(d);}}return out.sort((a,b)=>b.year-a.year||b.round-a.round||a.id.localeCompare(b.id));}
function prepareManagerNotebook(){
 const generation=++notebookGeneration;notebookRows=null;notebookSeriesRows=null;
 notebookDialog.innerHTML='<header><div><small>감독의 수첩</small><h2 id="notebook-title" tabindex="-1">함께 남긴 페이지</h2></div><button type="button" data-notebook-close aria-label="감독의 수첩 닫기">닫기</button></header><div class="notebook-cards notebook-loading"><p class="notebook-empty" role="status">지난 경기와 남긴 대답을 정리하고 있습니다…</p></div>';
 $('notebook-title').focus({preventScroll:true});
 requestAnimationFrame(()=>requestAnimationFrame(()=>{if(!notebookDialog.open||generation!==notebookGeneration)return;try{const rows=notebookScenes(),series=StorySerial.read(season);notebookRows=rows;notebookSeriesRows=series;renderManagerNotebook();$('notebook-title').focus({preventScroll:true});}catch(error){notebookDialog.innerHTML='<header><h2 id="notebook-title" tabindex="-1">수첩을 열지 못했습니다</h2><button type="button" data-notebook-close>닫기</button></header><div class="notebook-cards notebook-loading"><div class="notebook-empty" role="status"><p>기록을 정리하는 동안 문제가 생겼습니다.</p><button type="button" data-notebook-retry>다시 정리하기</button></div></div>';$('notebook-title').focus({preventScroll:true});}}));
}
function openManagerNotebook(trigger=document.activeElement,{tab='pending',page=0}={}){pauseForPlanning();notebookReturn=trigger;notebookPage=page;notebookTab=tab;notebookDialog.showModal();prepareManagerNotebook();}
function notebookTabs(all,active){
 const series=notebookSeriesRows||StorySerial.read(season),tabs=[['pending','도착한 이야기',all.filter(d=>d.year===season.year&&d.step<2).length],['complete','남긴 대답',all.filter(d=>d.step===2).length],['series','이어지는 이야기',series.length],['history','지난 시즌',all.filter(d=>d.year<season.year).length]];
 return '<nav class="notebook-tabs" aria-label="수첩 기록 종류">'+tabs.map(([id,label,count])=>'<button type="button" data-notebook-tab="'+id+'" aria-pressed="'+(id===active)+'" '+(id==='history'&&!count?'disabled':'')+'>'+label+' '+count+'</button>').join('')+'</nav>';
}
function serialNotebookMarkup(all){
 const series=notebookSeriesRows||StorySerial.read(season),esc=escapeText;
 return '<header><div><small>확정 경기와 직접 남긴 대답으로 이어지는 이야기</small><h2 id="notebook-title" tabindex="-1">한 번의 말, 그다음 두 경기</h2></div><button type="button" data-notebook-close aria-label="감독의 수첩 닫기">닫기</button></header>'+notebookTabs(all,'series')+'<div class="notebook-series">'+(series.length?series.map(a=>'<article class="serial-card">'+ClubArt.drama(a.drama)+'<div><h3>'+esc(a.title)+'</h3><small>'+esc(a.status)+'</small><p>'+a.facts.map(([label,value])=>esc(label)+': '+esc(value)).join(' · ')+'</p><div class="serial-stages" aria-label="'+esc(a.title)+' 장면">'+[1,2,3].map(episode=>{const stage=a.stages.find(e=>e.episode===episode),status=stage?(stage.step===2?'complete':'pending'):'locked';return '<button type="button" '+(stage?'data-notebook-event="'+stage.event+'"':'disabled')+' data-serial-state="'+status+'">'+episode+'화<span>'+(stage?(stage.step===2?'다시 읽기':stage.step===1?'대화 계속':'장면 읽기'):'기록 대기')+'</span></button>';}).join('')+'</div></div></article>').join(''):'<p class="notebook-empty">확정한 리그 경기에서 새 이야기가 시작됩니다. 크게 실점한 골키퍼, 계속 뛰는 선수, 원정 팬과 구단주의 목소리를 만나게 됩니다. 이야기를 읽는 것만으로 명단이나 결과가 바뀌지는 않습니다.</p>')+'</div><footer><span>1·2화 대답 뒤 리그 두 경기를 확정하면 다음 장면이 열립니다. 컵 경기와 진행 중인 경기는 포함되지 않습니다.</span></footer>';
}
function renderManagerNotebook(){
 const chapter=StoryNotebook.chapter(season),all=notebookRows||notebookScenes(),list=all.filter(d=>notebookTab==='complete'?d.step===2:notebookTab==='history'?d.year<season.year:d.year===season.year&&d.step<2),max=Math.max(0,Math.ceil(list.length/2)-1);notebookPage=Math.max(0,Math.min(max,notebookPage));
 if(notebookTab==='series'){notebookDialog.innerHTML=serialNotebookMarkup(all);ClubArt.fitDrama?.(notebookDialog);return;}
 const cards=list.slice(notebookPage*2,notebookPage*2+2),esc=escapeText;
 notebookDialog.innerHTML='<header><div><small>'+chapter.attempt+'번째 삶 · '+chapter.division+'부 · 감독의 수첩</small><h2 id="notebook-title" tabindex="-1">'+esc(chapter.title)+'</h2></div><button type="button" data-notebook-close aria-label="감독의 수첩 닫기">닫기</button></header>'+notebookTabs(all,notebookTab)+'<div class="notebook-cards">'+(cards.length?cards.map(d=>'<article class="notebook-card">'+storyArtwork(d)+'<div><small>'+d.year+'시즌 · '+d.round+'경기 뒤</small><h3>'+esc(d.title)+'</h3><p>'+esc(d.step===2?d.finalLabel:d.step===1?'첫 대답이 기록됐습니다. 대화를 이어갈 수 있습니다.':d.scene.split('\n\n')[0].split('\n')[0])+'</p><button type="button" data-notebook-event="'+d.id+'">'+(d.step===2?'내 대답 다시 읽기':d.readOnly?'지난 장면 읽기':d.step===1?'대화 이어가기':'이야기 만나기')+'</button></div></article>').join(''):'<p class="notebook-empty">'+(notebookTab==='history'?'아직 지난 시즌의 이야기가 없습니다. 시즌을 마치고 직접 다음 시즌을 시작하면 이곳에서 지난 장면을 읽을 수 있습니다.':notebookTab==='pending'?'지금 도착한 수첩 이야기를 모두 읽었습니다. 확정한 경기와 남긴 대답이 다음 페이지를 엽니다.':'아직 남긴 대답이 없습니다. 도착한 이야기를 읽고 직접 답하면 이곳에 남습니다.')+'</p>')+'</div><footer><button type="button" data-notebook-page="-1" '+(notebookPage===0?'disabled':'')+'>이전</button><span>'+(notebookPage+1)+' / '+(max+1)+'</span><button type="button" data-notebook-page="1" '+(notebookPage>=max?'disabled':'')+'>다음</button></footer>';
 ClubArt.fitDrama?.(notebookDialog);
}
notebookDialog.onclick=event=>{const close=event.target.closest('[data-notebook-close]'),tab=event.target.closest('[data-notebook-tab]'),page=event.target.closest('[data-notebook-page]'),scene=event.target.closest('[data-notebook-event]');if(close)return notebookDialog.close();if(event.target.closest('[data-notebook-retry]'))return prepareManagerNotebook();if(tab){notebookTab=tab.dataset.notebookTab;notebookPage=0;renderManagerNotebook();notebookDialog.querySelector('[data-notebook-tab="'+notebookTab+'"]').focus({preventScroll:true});}else if(page&&!page.disabled){notebookPage+=Number(page.dataset.notebookPage);renderManagerNotebook();$('notebook-title').focus({preventScroll:true});}else if(scene){const context={tab:notebookTab,page:notebookPage,opener:notebookReturn};notebookDialog.close();openClubStory(scene.dataset.notebookEvent,notebookReturn,false,context);}};
notebookDialog.addEventListener('close',()=>{if(notebookDialog.open)return;notebookRows=null;notebookSeriesRows=null;notebookGeneration++;if(notebookReturn?.isConnected&&!notebookReturn.closest('dialog'))notebookReturn.focus({preventScroll:true});});
